int body_rects_on_page(int page = 0) {
    int n = 0;
    for (int i = 0; i < g_c.n_rec; ++i) {
        const Canvas::Rec& r = g_c.rec[i];
        if (r.is_text || r.page != page || strcmp(r.s, "[rect]") != 0) continue;
        if (!(r.x == kRailX && r.w == kRailW)) ++n;
    }
    return n;
}
